import{_ as t,o as e,c as o,Q as r}from"./chunks/framework.b67c47e6.js";const m=JSON.parse('{"title":"Quality Control Report","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/quality_control/index.md","filePath":"guide/reports/quality_control/index.md","lastUpdated":1789501320000}'),a={name:"guide/reports/quality_control/index.md"},n=r('<h1 id="quality-control-report" tabindex="-1">Quality Control Report <a class="header-anchor" href="#quality-control-report" aria-label="Permalink to &quot;Quality Control Report&quot;">​</a></h1><p>The Quality Control Report generates a PDF summarizing all quality control records for your constructibles.</p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> PDF</li><li><strong>Content:</strong> Quality control issues logged during production, including descriptions, categories, status, and resolution details.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>This report is available both at <strong>project level</strong> and <strong>company level</strong>.</p><ul><li><strong>Project level</strong> — Select specific assemblies or modules to include.</li><li><strong>Company level</strong> — Use a date range and optionally filter by production line.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Date range</strong></td><td>Start and end date for filtering (company-level reports).</td></tr><tr><td><strong>Production line</strong></td><td>Filter results to a specific production line (company-level reports).</td></tr></tbody></table><h2 id="who-did-what" tabindex="-1">Who did what <a class="header-anchor" href="#who-did-what" aria-label="Permalink to &quot;Who did what&quot;">​</a></h2><p>Every checklist item in the report says <strong>who ticked it</strong>, and every picture says <strong>who uploaded it and when</strong>. The two are separate on purpose: the person who takes the photo is often not the one who ticks the box.</p><p>The name is the <strong>alias</strong> of the employees who were working under the account at that moment. When nobody was named — an older record, or an account with no employees selected — the account name is shown instead, and a picture uploaded before this was recorded says <em>No author recorded</em> rather than borrowing the name of whoever ticked the task.</p><p>The same information is on the panel itself, in the <strong>Production Proof</strong> card of the constructible detail page.</p><p>See: <a href="/guide/viewer/">Who is working</a> for how employees are selected on the shop floor.</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>Use this report for quality audits, compliance reviews, and tracking quality trends across your production.</p>',16),i=[n];function s(l,d,h,c,p,u){return e(),o("div",null,i)}const f=t(a,[["render",s]]);export{m as __pageData,f as default};
